def backfill_induction_expiry(apps, schema_editor):
    EmployeeInduction = apps.get_model("induction", "EmployeeInduction")
    database = schema_editor.connection.alias
    for induction in EmployeeInduction.objects.using(database).filter(
        status="completed",
        completed_at__isnull=False,
    ).iterator():
        completed_date = timezone.localtime(induction.completed_at).date()
        month_index = completed_date.month - 1 + induction.expiry_months
        year = completed_date.year + month_index // 12
        month = month_index % 12 + 1
        day = min(
            completed_date.day,
            calendar.monthrange(year, month)[1],
        )
        induction.expires_on = completed_date.replace(
            year=year,
            month=month,
            day=day,
        )
        induction.save(update_fields=["expires_on"], using=database)


